begin;
-- Additive relaunch: existing letters, profiles, postcards and moments are retained.
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;
create table private.members (id uuid primary key references auth.users(id), email text not null unique);
alter table private.members enable row level security;
do $$ begin if (select count(*) from public.profiles) <> 2 then raise exception 'Expected the existing two profiles; membership seed requires review'; end if; end $$;
insert into private.members select id, lower(email) from public.profiles;
create function private.is_member(candidate uuid default auth.uid()) returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from private.members where id = candidate) and exists (select 1 from private.members where id = (select auth.uid())); $$;
revoke all on function private.is_member(uuid) from public, anon;
grant execute on function private.is_member(uuid) to authenticated;
revoke execute on function public.handle_new_user() from public, anon, authenticated;
-- Restrictive policies combine with the existing policies; nothing is dropped.
create policy "Members view profiles" on public.profiles as restrictive for select to authenticated using ((select private.is_member()) and private.is_member(id));
create policy "Members view moments" on public.moments as restrictive for select to authenticated using ((select private.is_member()));
create policy "Members add own moments" on public.moments as restrictive for insert to authenticated with check ((select private.is_member()) and created_by=(select auth.uid()));
create policy "Members update own moments" on public.moments as restrictive for update to authenticated using ((select private.is_member()) and created_by=(select auth.uid())) with check ((select private.is_member()) and created_by=(select auth.uid()));
create policy "Members send to members" on public.letters as restrictive for insert to authenticated with check ((select private.is_member()) and from_id=(select auth.uid()) and to_id<>from_id and exists (select 1 from public.profiles where id=to_id));
create policy "Members send postcards" on public.postcards as restrictive for insert to authenticated with check ((select private.is_member()) and from_id=(select auth.uid()) and to_id<>from_id and exists (select 1 from public.profiles where id=to_id));
-- Column privileges prevent rewriting sealed letters via the REST API.
revoke update on public.letters from authenticated;
grant update(read_at) on public.letters to authenticated;
revoke update on public.postcards from authenticated;
grant update(read_at) on public.postcards to authenticated;
create table public.letter_drafts (user_id uuid primary key references public.profiles(id), id uuid not null unique default gen_random_uuid(), subject text not null default '', body text not null default '', updated_at timestamptz not null default now());
create table public.checkins (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), mood text not null check(length(mood) between 1 and 80), energy text not null default 'steady', need text not null default '', phase text not null default '', cycle_phase text, note text not null default '', created_at timestamptz not null default now());
create table public.checkin_private (id uuid primary key references public.checkins(id), user_id uuid not null references public.profiles(id), cycle_phase text, note text not null default '');
create table public.library_items (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), kind text not null check(kind in ('book','video','article')), title text not null check(length(title) between 1 and 250), author text not null default '', url text, status text not null default 'want' check(status in ('want','reading','finished')), progress integer not null default 0 check(progress between 0 and 100), created_at timestamptz not null default now());
create table public.library_notes (id uuid primary key default gen_random_uuid(), item_id uuid not null references public.library_items(id), user_id uuid not null references public.profiles(id), body text not null check(length(body) between 1 and 10000), is_private boolean not null default true, created_at timestamptz not null default now());
create table public.plans (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), title text not null check(length(title) between 1 and 250), note text not null default '', energy text not null default 'gentle' check(energy in ('gentle','steady','adventurous')), planned_for date, status text not null default 'idea' check(status in ('idea','planned','done')), created_at timestamptz not null default now());
alter table public.checkins enable row level security;
grant select, insert, update on public.checkins to authenticated;
create policy "Members read checkins" on public.checkins for select to authenticated using ((select private.is_member()));
create policy "Members insert own checkins" on public.checkins for insert to authenticated with check ((select private.is_member()) and user_id=(select auth.uid()));
create policy "Members update own checkins" on public.checkins for update to authenticated using ((select private.is_member()) and user_id=(select auth.uid())) with check ((select private.is_member()) and user_id=(select auth.uid()));
alter table public.library_items enable row level security;
grant select, insert, update on public.library_items to authenticated;
create policy "Members read library_items" on public.library_items for select to authenticated using ((select private.is_member()));
create policy "Members insert own library_items" on public.library_items for insert to authenticated with check ((select private.is_member()) and user_id=(select auth.uid()));
create policy "Members update own library_items" on public.library_items for update to authenticated using ((select private.is_member()) and user_id=(select auth.uid())) with check ((select private.is_member()) and user_id=(select auth.uid()));
alter table public.plans enable row level security;
grant select, insert, update on public.plans to authenticated;
create policy "Members read plans" on public.plans for select to authenticated using ((select private.is_member()));
create policy "Members insert own plans" on public.plans for insert to authenticated with check ((select private.is_member()) and user_id=(select auth.uid()));
create policy "Members update own plans" on public.plans for update to authenticated using ((select private.is_member()) and user_id=(select auth.uid())) with check ((select private.is_member()) and user_id=(select auth.uid()));
alter table public.letter_drafts enable row level security;
grant select, insert, update on public.letter_drafts to authenticated;
create policy "Owner reads letter_drafts" on public.letter_drafts for select to authenticated using ((select private.is_member()) and user_id=(select auth.uid()));
create policy "Owner inserts letter_drafts" on public.letter_drafts for insert to authenticated with check ((select private.is_member()) and user_id=(select auth.uid()) );
create policy "Owner updates letter_drafts" on public.letter_drafts for update to authenticated using ((select private.is_member()) and user_id=(select auth.uid())) with check ((select private.is_member()) and user_id=(select auth.uid()));
alter table public.checkin_private enable row level security;
grant select, insert, update on public.checkin_private to authenticated;
create policy "Owner reads checkin_private" on public.checkin_private for select to authenticated using ((select private.is_member()) and user_id=(select auth.uid()));
create policy "Owner inserts checkin_private" on public.checkin_private for insert to authenticated with check ((select private.is_member()) and user_id=(select auth.uid()) and exists(select 1 from public.checkins where id=checkin_private.id and user_id=(select auth.uid())));
create policy "Owner updates checkin_private" on public.checkin_private for update to authenticated using ((select private.is_member()) and user_id=(select auth.uid())) with check ((select private.is_member()) and user_id=(select auth.uid()) and exists(select 1 from public.checkins where id=checkin_private.id and user_id=(select auth.uid())));
alter table public.library_notes enable row level security;
grant select, insert, update on public.library_notes to authenticated;
create policy "Owner reads library_notes" on public.library_notes for select to authenticated using ((select private.is_member()) and (user_id=(select auth.uid()) or not is_private));
create policy "Owner inserts library_notes" on public.library_notes for insert to authenticated with check ((select private.is_member()) and user_id=(select auth.uid()) );
create policy "Owner updates library_notes" on public.library_notes for update to authenticated using ((select private.is_member()) and user_id=(select auth.uid())) with check ((select private.is_member()) and user_id=(select auth.uid()));
grant delete on public.letter_drafts to authenticated;
create policy "Owner deletes draft" on public.letter_drafts for delete to authenticated using ((select private.is_member()) and user_id=(select auth.uid()));
-- Check-in and its private fields save in one transaction.
create function public.save_checkin(payload jsonb) returns uuid language plpgsql security invoker set search_path = '' as $$
declare entry_id uuid;
begin
insert into public.checkins(user_id,mood,energy,need,phase,cycle_phase,note) values(auth.uid(),payload->>'mood',payload->>'energy',payload->>'need',payload->>'phase',case when (payload->>'share_cycle')::boolean then nullif(payload->>'cycle_phase','') else null end,case when (payload->>'share_note')::boolean then payload->>'note' else '' end) returning id into entry_id;
insert into public.checkin_private(id,user_id,cycle_phase,note) values(entry_id,auth.uid(),nullif(payload->>'cycle_phase',''),payload->>'note');
return entry_id;
end; $$;
revoke all on function public.save_checkin(jsonb) from public,anon;
grant execute on function public.save_checkin(jsonb) to authenticated;
create index checkins_user_date_idx on public.checkins(user_id,created_at desc);
create index library_notes_item_idx on public.library_notes(item_id,created_at);
create index plans_date_idx on public.plans(planned_for);
create policy "Members view letters" on public.letters as restrictive for select to authenticated using ((select private.is_member()));
create policy "Members view postcards" on public.postcards as restrictive for select to authenticated using ((select private.is_member()));
commit;
